/* A live optical view of the globe, rendered onto an in-world eyepiece. */
AFRAME.registerComponent('scope-renderer',{
 init(){this.zoom=1;this.active=false;this.last=0;this.camera=new AFRAME.THREE.PerspectiveCamera(52,1,.05,30);this.target=new AFRAME.THREE.WebGLRenderTarget(512,512,{depthBuffer:true});this.target.texture.colorSpace=AFRAME.THREE.SRGBColorSpace;this.position=new AFRAME.THREE.Vector3();this.aim=new AFRAME.THREE.Vector3()},
 foreground(){document.getElementById('scopeView')?.object3D.traverse(o=>{if(!o.isMesh)return;o.renderOrder=o.userData.panelPriority||24000;for(const m of Array.isArray(o.material)?o.material:[o.material]){if(!m)continue;m.depthTest=false;m.depthWrite=false;if(!m.transparent){m.transparent=true;m.needsUpdate=true}}})},
 tick(time){if(this.active)this.foreground();if(!this.active||window.globiquest?.scopeCountriesOpen||time-this.last<120)return;const scene=this.el.sceneEl,renderer=scene.renderer,planet=document.getElementById('planet')?.getObject3D('mesh');if(!renderer||!planet)return;this.last=time;const T=AFRAME.THREE;document.getElementById('mapRoot').object3D.traverse(o=>o.layers.enable(2));scene.object3D.traverse(o=>{if(o.isLight)o.layers.enable(2)});this.camera.layers.set(2);planet.getWorldPosition(this.position);this.camera.position.copy(this.position).add(new T.Vector3(0,.13,3.5));this.aim.copy(this.position);const selectedCountry=window.globiquest.scopePreviewCountry?.()||window.globiquest.scopeCountry;if(this.zoom>1&&selectedCountry){const country=selectedCountry,p=mapPoint(country.lat,country.lon,1.18),point=window.globiquest.globePatch?.root?.visible&&window.globiquest.globePatch?.country?.id===country.id?window.globiquest.globePatch.root.getWorldPosition(new T.Vector3()):planet.localToWorld(new T.Vector3(p.x,p.y,p.z));this.aim.lerp(point,(this.zoom-1)/3)}else if(this.zoom>1){const pin=document.getElementById('pins').children[window.globiquest.state.place];if(pin){const point=new T.Vector3();pin.object3D.getWorldPosition(point);this.aim.lerp(point,(this.zoom-1)/3)}}this.camera.lookAt(this.aim);this.camera.fov=52/this.zoom;this.camera.updateProjectionMatrix();const previous=renderer.getRenderTarget(),xr=renderer.xr.enabled,background=scene.object3D.background;try{renderer.xr.enabled=false;scene.object3D.background=new T.Color('#2c425a');renderer.setRenderTarget(this.target);renderer.render(scene.object3D,this.camera)}finally{renderer.setRenderTarget(previous);renderer.xr.enabled=xr;scene.object3D.background=background}const mesh=this.el.getObject3D('mesh');if(mesh&&mesh.material.map!==this.target.texture){mesh.material.map=this.target.texture;mesh.material.needsUpdate=true}this.identify()},
 identify(){const T=AFRAME.THREE,planet=document.getElementById('planet')?.getObject3D('mesh');if(!planet||typeof destinations==='undefined')return;const origin=this.camera.getWorldPosition(new T.Vector3()),direction=this.camera.getWorldDirection(new T.Vector3()),center=planet.getWorldPosition(new T.Vector3()),radius=1.18*planet.getWorldScale(new T.Vector3()).x;const point=new T.Ray(origin,direction).intersectSphere(new T.Sphere(center,radius),new T.Vector3());let picked=null;if(point){const local=planet.worldToLocal(point).normalize();let best=-1,index=-1;destinations.forEach((d,i)=>{const p=mapPoint(d[3],d[4]),dot=local.dot(new T.Vector3(p.x,p.y,p.z));if(dot>best){best=dot;index=i}});if(best>Math.cos(Math.PI/6))picked={index,angle:Math.acos(Math.min(1,best))*180/Math.PI}}const country=window.globiquest.scopePreviewCountry?.()||window.globiquest.scopeCountry;if(country)picked=Number.isInteger(country.destination)?{index:country.destination,angle:0}:null;this.place=picked;window.globiquest.scopePlace=picked;window.globiquest.updateScopeCaption?.(picked,this.zoom);const label=document.getElementById('scopePlaceName');if(label){const d=picked?destinations[picked.index]:null;label.setAttribute('value',country?country.name+' · '+country.region+' · '+this.zoom+'x':d?'Nearest: '+d[0]+', '+d[1]+' · '+this.zoom+'x':'Ocean / no nearby saved place · '+this.zoom+'x')}},
 remove(){this.target.dispose()}
});
